insert into
  checkout_session_items (
    session_id,
    position,
    drink_id,
    drink_name,
    size,
    milk,
    temperature,
    shots,
    notes,
    quantity,
    unit_price_cents,
    line_total_cents
  )
values
  (
    :item.sessionId,
    :item.position,
    :item.drinkId,
    :item.drinkName,
    :item.size,
    :item.milk,
    :item.temperature,
    :item.shots,
    :item.notes,
    :item.quantity,
    :item.unitPriceCents,
    :item.lineTotalCents
  );
